import{c as a,Q as s,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"HcclServerType","description":"","frontmatter":{},"headers":[{"level":1,"title":"HcclServerType","slug":"hcclservertype"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/原型注册与管理/OpMC2Def/HcclServerType.md","filePath":"api/Utils-API/原型注册与管理/OpMC2Def/HcclServerType.md"}'),p={name:"api/Utils-API/原型注册与管理/OpMC2Def/HcclServerType.md"};function l(r,e,c,i,o,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="hcclservertype" tabindex="-1">HcclServerType <a class="header-anchor" href="#hcclservertype" aria-label="Permalink to &quot;HcclServerType&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>配置HCCL的服务端类型。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void HcclServerType(enum HcclServerType type, const char *soc=nullptr)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>type</td><td>输入</td><td>HCCL的服务端类型，类型为HcclServerType枚举类，定义如下： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen112171935175919&quot;&gt;namespace ops{ enum HcclServerType : uint32_t { AICPU = 0, // AI CPU服务端 AICORE, // AI Core服务端 CCU, // CCU服务端，仅在AI处理器包含CCU单元时支持 MAX // 预留参数，不支持使用 }; }&lt;/pre&gt;</td></tr><tr><td>soc</td><td>输入</td><td>AI处理器型号。为该型号配置服务端类型。 可选参数，nullptr或者&quot;&quot;表示为算子支持的所有型号配置服务端类型。 soc取值需确保在算子支持的AI处理器型号范围内，即已经调用AddConfig接口注册。 填写规则请参考算子工程目录下编译配置项文件CMakePresets.json中的ASCEND_COMPUTE_UNIT字段，该字段取值在使用msOpGen创建工程时自动生成。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>使用该接口前，算子需要先通过<a href="./../OpDef/MC2.html">MC2</a>接口注册该算子是通算融合算子，注册后即返回一个<a href="./OpMC2Def.html">OpMC2Def</a>结构。</li><li>同时为特定AI处理器型号和所有AI处理器型号配置服务端类型时，特定AI处理器型号配置的优先级更高。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class MC2Custom : public OpDef {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    MC2Custom(const char* name) : OpDef(name)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;).ParamType(REQUIRED).DataType({ge::DT_FLOAT}).Format({ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Input(&quot;y&quot;).ParamType(REQUIRED).DataType({ge::DT_FLOAT}).Format({ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;z&quot;).ParamType(REQUIRED).DataType({ge::DT_FLOAT}).Format({ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Attr(&quot;group&quot;).AttrType(REQUIRED).String();</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx1&quot;);</span></span>
<span class="line"><span>        this-&gt;AICore().AddConfig(&quot;ascendxxx2&quot;);</span></span>
<span class="line"><span>        this-&gt;MC2().HcclGroup(&quot;group&quot;); // 配置通信域名称为group</span></span>
<span class="line"><span>        this-&gt;MC2().HcclServerType(HcclServerType::AICPU, &quot;ascendxxx1&quot;); // 配置ascendxxx1型号的通信模式为AI CPU</span></span>
<span class="line"><span>        this-&gt;MC2().HcclServerType(HcclServerType::AICORE); // 配置其他型号即ascendxxx2的通信模式为AI Core</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>OP_ADD(MC2Custom);</span></span></code></pre></div>`,11)])])}const C=a(p,[["render",l]]);export{h as __pageData,C as default};
